import { gunzipSync } from 'node:zlib';

// Compressed byte fixture for the retired managed plugin. It is inspected and
// deleted by upgrade tests; it is never loaded as JavaScript.
const LEGACY_OPENCODE_LOOP_GUARD_GZIP_BASE64 = '';

export const LEGACY_CLAUDE_PROMPT_HOOK = Object.freeze({
  type: 'mcp_tool',
  server: 'kiokuko',
  tool: 'claude_prompt_context',
  input: { prompt: '${prompt}', cwd: '${cwd}', sessionId: '${session_id}' },
  timeout: 5,
  statusMessage: 'Kiokuko: recalling relevant memory',
});

export function legacyOpenCodeLoopGuardFixture(): string {
  return gunzipSync(Buffer.from(LEGACY_OPENCODE_LOOP_GUARD_GZIP_BASE64, 'base64')).toString('utf8');
}
